// Key: `#Target(Web)` chooses the web target.
// `route` maps a URL to a page; `csr` renders in the browser.
// `island` marks an interactive part; `a11y` records accessibility settings.
// `adapter` selects the runtime; `hydration_dev` checks browser/server handoff.
use core.web as web
#Target(Web)

fn home() WebPage -> web.page("Home", "hello from csr")
fn save() { print("saved") }
fn api_mount(prefix: String) { print(prefix) }

fn run() App -> {
    return web.app()
        .csr()
        .route("/", home)
        .action("save", save)
        .mount("/api", api_mount, "Net", "csrf")
        .island()
        .route("/widget", home)
        .security("csp-default")
        .assets("examples/features/web/public")
        .split("widget")
        .cache("revalidate")
        .a11y("wcag-aa")
        .adapter("node")
        .hydration_dev()
}

