// payments/src/devtools.jet
use core.ui as ui
use core.devtools as devtools // proposed

struct PaymentSettled {
    invoice_id: String
    cents: Int
}

struct PaymentsState {
    last_invoice: String{""}     // defaults: the panel renders before its first publication
    settled_cents: Int{0}
    card_suffix: String{""}
}

#DevPanel // proposed marker
pub fn payments_panel(state: PaymentsState) UiNode -> { // proposed typed parameter
    return ui.box([
        ui.text("Payments"),
        ui.text("Invoice: {state.last_invoice}"),
        ui.text("Settled cents: {state.settled_cents}"),
        ui.text("Card suffix: {state.card_suffix}")
    ])
}

#Scrub(Credential)
fn card_suffix(card: #Credential String) String -> { return card.suffix(4) }   // the one place a credential is reduced

pub fn settle(invoice_id: String, cents: Int, card: #Credential String) {
    event :: PaymentSettled{invoice_id: ~invoice_id, cents: cents} // proposed typed event
    devtools.publish("payments.settled", event, value: invoice_id, field: .last_invoice)   // proposed: each site names its state field
    devtools.publish("payments.settled", event, value: cents, field: .settled_cents)
    devtools.publish("payments.card", event, value: card_suffix(card), field: .card_suffix)
}

fn inspect_card(card: #Credential String) {
    devtools.publish("payments.card", event, card_suffix(card)) // proposed misuse: unlabelled value
    // error E1404 (proposed)
    // what: this published value has no gate.
    // why: a published value must name itself with `value:` and its state field with `field:`.
    // fix: devtools.publish("payments.card", event, value: card_suffix(card), field: .card_suffix)
    devtools.publish("payments.card", event, value: card, field: .card_suffix)
    // error E0722: a `#Credential` value reaches a publish sink; scrub it first
}

// jet check (illustrative), after adding refund_count: Int{0} to PaymentsState with no site:
