use core.process as process

// A parse-or-die helper: the most common non-returning function in real tools.
// process.exit(2) stops the program with failure code 2 and produces no value.
fn usage() {
    print("usage: tool <count>")
    process.exit(2)
}

fn count(arg: String) Int -> {
    return Int.parse(arg) ?? usage()   // fallback: when parsing fails, call usage()
}

