#include <cassert>
int main() {
    auto d = rules::Document::open({10,20,30}).value();
    auto v = d.bytes();
    assert(v.at(1).value() == 20);
    d.replace({40,50}).value();
    assert(v.at(1).error() == rules::Error::ExpiredView);
    assert(d.bytes().at(1).value() == 50);
    d.close().value();
}
```

**Rust**

```rust
