```typescript
import 'reflect-metadata';
import { Body, Controller, Header, HttpCode, Module, Post, UnprocessableEntityException } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { ApiBody, ApiOperation, ApiResponse, DocumentBuilder, SwaggerModule } from '@nestjs/swagger';
import { writeFileSync } from 'node:fs';
type NewOrder = { sku: string };
function createOrder(input: NewOrder): string {
  if (input.sku === '') throw new Error('sku_required');
  const stored = { id: 'order-41', sku: input.sku, internal_note: 'supplier-cost=19' };
  return stored.id;
}
@Controller('actions')
class OrdersController {
  @Post('create-order') @HttpCode(200)
  @Header('content-type', 'application/json')
  @ApiOperation({ operationId: 'create-order' })
  @ApiBody({ schema: { type: 'object', required: ['sku'], properties: { sku: { type: 'string' } } } })
  @ApiResponse({ status: 200, schema: { type: 'string' }, description: 'Order ID' })
  @ApiResponse({ status: 422, description: 'Rejected order' })
  create(@Body() input: NewOrder): string {
    try { return JSON.stringify(createOrder(input)); }
    catch { throw new UnprocessableEntityException('sku_required'); }
  }
}
@Module({ controllers: [OrdersController] })
class AppModule {}
async function main() {
  const app = await NestFactory.create(AppModule);
  const config = new DocumentBuilder().setTitle('Orders').setVersion('1').build();
  await app.init();
  const document = SwaggerModule.createDocument(app, config);
  writeFileSync('openapi.json', JSON.stringify(document));
  await app.listen(3000, '127.0.0.1');
}
void main();
```

