### server.ts — complete in-the-wild server adaptation

```typescript
import "reflect-metadata";
import { Controller, Module } from "@nestjs/common";
import { NestFactory } from "@nestjs/core";
import { Ctx, EventPattern, Payload, RmqContext, Transport } from "@nestjs/microservices";
import type { MicroserviceOptions } from "@nestjs/microservices";
import { recordOrderOnce } from "./orders.js";
import type { Order } from "./orders.js";

@Controller()
class OrdersConsumer {
  @EventPattern("orders")
  async record(@Payload() order: Order, @Ctx() context: RmqContext) {
    await recordOrderOnce(order);
    if (process.env.HOLD_AFTER_RECORD === "1") await new Promise<void>(() => {});
    context.getChannelRef().ack(context.getMessage());
  }
}
@Module({ controllers: [OrdersConsumer] })
class AppModule {}
const app = await NestFactory.createMicroservice<MicroserviceOptions>(AppModule, {
  transport: Transport.RMQ,
  options: {
    urls: ["amqp://orders:orders-local-only@127.0.0.1:5672"], queue: "orders",
    queueOptions: { durable: false }, noAck: false, prefetchCount: 1
  }
});
app.enableShutdownHooks();
await app.listen();
```


