    request :: client.request("POST", "http://127.0.0.1:8089/orders").json(input)
    response :: request.send() ?? return Err("ledger completion unknown")
    if response.status() != 200 -> return Err("ledger rejected order")
    receipt :: response.body().text(1024) ?? return Err("ledger reply unreadable")
    return Ok(receipt)
}
fn app() App -> web.app().action("record-order", record_order)
