use core.jobs as jobs
use invoice as work
fn run() {
    queue :: jobs.queue() ?? panic("queue open failed")
    _ :: queue.recover_expired() ?? panic("recovery failed")
    claims :: queue.claim("worker-b", 1) ?? panic("claim failed")
    assert(claims.len() == 1)
    loop claim in claims {
        work.Invoice("order-41")
        result :: JobResult{
            type_id: claim.payload.type_id,
            bytes: claim.payload.bytes,
            publish: false,
        }
        _ :: queue.acknowledge(claim, result) ?? panic("acknowledgement failed")
        _ :: queue.receipt(claim.receipt.id) ?? panic("receipt read failed")
        _ :: queue.events(claim.receipt.id) ?? panic("event read failed")
    }
    status :: queue.status() ?? panic("status failed")
    assert(status.completed == 1)
}
