});
const module = CacheModule.register({ stores: [store] });
// The full module defines both HTTP processes and cache injection.
// POST /write stores false; GET /value returns {hit:true,value:false}.
// DELETE /value removes it; GET /value then returns {hit:false}.
// Remote invalidation, expiry and outage outcomes are NOT RUN.
