```typescript
import 'reflect-metadata';
import { Controller, Delete, Get, Inject, Module, Post } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { CacheModule, CACHE_MANAGER, Cache } from '@nestjs/cache-manager';
import { Keyv } from 'keyv';
import KeyvRedis from '@keyv/redis';
const redis = new KeyvRedis('redis://127.0.0.1:6380/0');
const store = new Keyv({ store: redis, namespace: 'orders' });
@Controller()
class OrderCache {
  constructor(@Inject(CACHE_MANAGER) private readonly cache: Cache) {}
  @Post('write') async write() {
    await this.cache.set('order-41', false, 1000);
    return { written: true };
  }
  @Get('value') async value() {
    const value = await this.cache.get('order-41');
    return value === undefined || value === null
      ? { hit: false } : { hit: true, value };
  }
  @Delete('value') async invalidate() {
    await this.cache.del('order-41');
    return { removed: true };
  }
}
@Module({
  imports: [CacheModule.register({ stores: [store] })],
  controllers: [OrderCache],
})
class CacheApp {}
const port = Number(process.env.PORT);
if (port !== 3001 && port !== 3002) throw new Error('PORT must be 3001 or 3002');
const app = await NestFactory.create(CacheApp);
await app.listen(port, '127.0.0.1');
```

