fn run() {
    log.set_sink("jsonl", "orders-api.jsonl")
    log.set_trace_id("4bf92f3577b34da6a3ce929d0e0e4736")
    log.info_fields("order.completed", [
        log.field("service", "orders-api"), log.field("order", "order-41"),
        log.redact("token"),
