```javascript
import { createServer } from 'node:http';
import { appendFile } from 'node:fs/promises';
const expectedTrace = process.env.EXPECT_TRACE;
if (!/^[0-9a-f]{32}$/.test(expectedTrace || '')) throw new Error('EXPECT_TRACE is required');
const server = createServer(async (req, res) => {
  if (req.method !== 'POST' || req.url !== '/events') {
    res.writeHead(404).end(); return;
  }
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (Buffer.byteLength(body) > 4096) { res.writeHead(413).end(); return; }
  }
  try {
    const record = JSON.parse(body);
    const keys = Object.keys(record).sort().join(',');
    if (keys !== 'order,service,trace_id' || record.trace_id !== expectedTrace ||
        record.order !== 'order-41' ||
        !['orders-api', 'invoices-api'].includes(record.service)) {
      res.writeHead(422).end(); return;
    }
    await appendFile('received.jsonl', JSON.stringify(record) + '\n');
    res.writeHead(204).end();
  } catch { res.writeHead(400).end(); }
});
server.listen(4318, '127.0.0.1');
