```javascript
// services.mjs. AUTHORED NOT RUN. Run once per role.
import { createServer } from 'node:http';
import { appendFile } from 'node:fs/promises';
const service = process.argv[2];
if (!['orders-api', 'invoices-api'].includes(service)) throw new Error('invalid role');
const port = service === 'orders-api' ? 3001 : 3002;
const server = createServer(async (req, res) => {
  if (req.method !== 'POST' || req.url !== '/order') { res.writeHead(404).end(); return; }
  const header = req.headers.traceparent;
  const match = typeof header === 'string' && /^00-([0-9a-f]{32})-([0-9a-f]{16})-01$/.exec(header);
  if (!match || /^0+$/.test(match[1]) || /^0+$/.test(match[2])) { res.writeHead(400).end(); return; }
  try {
    if (service === 'orders-api') {
      const downstream = await fetch('http://127.0.0.1:3002/order', {
        method: 'POST', headers: { traceparent: header }, signal: AbortSignal.timeout(1000),
      });
      if (downstream.status !== 200 || await downstream.text() !== 'order-41') {
        res.writeHead(502).end(); return;
      }
    }
    const record = { trace_id: match[1], service, order: 'order-41', token: '[redacted]' };
    await appendFile(`${service}.jsonl`, JSON.stringify(record) + '\n');
    res.writeHead(200).end('order-41');
  } catch { res.writeHead(502).end(); }
});
server.listen(port, '127.0.0.1');
```

