import 'reflect-metadata';
import { Module } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { Args, GraphQLModule, Mutation, Query, Resolver } from '@nestjs/graphql';
import { ApolloDriver, ApolloDriverConfig } from '@nestjs/apollo';
import { GraphQLError } from 'graphql';
type NewOrder = { sku: string };
function createOrder(input: NewOrder): string {
  if (input.sku === '') throw new Error('sku_required');
  const stored = { id: 'order-41', sku: input.sku, internal_note: 'supplier-cost=19' };
  return stored.id;
}
@Resolver()
class OrdersResolver {
  @Query(() => Boolean) ready(): boolean { return true; }
  @Mutation(() => String)
  createOrder(@Args('sku', { type: () => String }) sku: string): string {
    try { return createOrder({ sku }); }
    catch { throw new GraphQLError('sku_required', { extensions: { code: 'SKU_REQUIRED' } }); }
  }
}
@Module({
  imports: [GraphQLModule.forRoot<ApolloDriverConfig>({
    driver: ApolloDriver, autoSchemaFile: true, path: '/graphql', includeStacktraceInErrorResponses: false
  })],
  providers: [OrdersResolver]
})
class AppModule {}
async function main() {
  const app = await NestFactory.create(AppModule);
  await app.listen(3000, '127.0.0.1');
}
void main();
```

