```python
# Authored local fixture; NOT RUN. Python 3.12.10, standard library only.
import json
import re
import sqlite3
from http.server import BaseHTTPRequestHandler, HTTPServer

DB = "orders.sqlite3"
with sqlite3.connect(DB) as db:
    db.execute("CREATE TABLE IF NOT EXISTS charges (id TEXT PRIMARY KEY, sku TEXT NOT NULL, cents INTEGER NOT NULL)")

class Handler(BaseHTTPRequestHandler):
    def reply(self, status, body, content_type="text/plain"):
        data = body.encode()
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def do_POST(self):
        if self.path != "/orders":
            self.reply(404, "not found")
            return
        try:
            size = int(self.headers.get("Content-Length", "0"))
            if not 0 < size <= 1024:
                raise ValueError("body size")
            order = json.loads(self.rfile.read(size))
            if not isinstance(order, dict) or set(order) != {"id", "sku"}:
                raise ValueError("fields")
            if not isinstance(order["id"], str) or not re.fullmatch(r"order-[0-9]+", order["id"]):
                raise ValueError("id")
            if order["sku"] != "book":
                raise ValueError("sku")
        except (ValueError, TypeError):
            self.reply(400, "invalid order")
            return
        try:
            with sqlite3.connect(DB) as db:
                db.execute("INSERT INTO charges VALUES (?, ?, 2500) ON CONFLICT(id) DO NOTHING",
                           (order["id"], order["sku"]))
            # The transaction has committed before the HTTP success response.
        except sqlite3.Error:
            self.reply(503, "ledger unavailable")
            return
        self.reply(200, "recorded " + order["id"])

    def do_GET(self):
        if self.path != "/charges":
            self.reply(404, "not found")
            return
        with sqlite3.connect(DB) as db:
            rows = db.execute("SELECT id, sku, cents FROM charges ORDER BY id").fetchall()
        body = {"charges": [dict(zip(("id", "sku", "cents"), row)) for row in rows],
                "total_cents": sum(row[2] for row in rows)}
        self.reply(200, json.dumps(body, separators=(",", ":")), "application/json")

HTTPServer(("127.0.0.1", 8089), Handler).serve_forever()
```


