### server.ts — complete in-the-wild server adaptation

```typescript
import "reflect-metadata";
import { Controller, Get, Inject, Module } from "@nestjs/common";
import { NestFactory } from "@nestjs/core";
import { ConnectedSocket, MessageBody, SubscribeMessage, WebSocketGateway } from "@nestjs/websockets";
import type { Socket } from "socket.io";
import { recordOrderOnce } from "./orders.js";
import type { Order } from "./orders.js";

@WebSocketGateway({ path: "/socket.io", transports: ["websocket"] })
class OrdersGateway {
  readonly connections = new Map<string, AbortController>();
  pending = 0;
  handleConnection(socket: Socket) { this.connections.set(socket.id, new AbortController()); }
  handleDisconnect(socket: Socket) {
    this.connections.get(socket.id)?.abort();
    this.connections.delete(socket.id);
  }
  @SubscribeMessage("order")
  async record(@MessageBody() order: Order, @ConnectedSocket() socket: Socket) {
    const lifetime = this.connections.get(socket.id);
    if (!lifetime) throw new Error("connection closed");
    this.pending++;
    try { return await recordOrderOnce(order, lifetime.signal); }
    finally { this.pending--; }
  }
}
@Controller()
class FixtureStatus {
  constructor(@Inject(OrdersGateway) private readonly gateway: OrdersGateway) {}
  @Get("connections")
  status() { return { connections: this.gateway.connections.size, pending: this.gateway.pending }; }
}
@Module({ providers: [OrdersGateway], controllers: [FixtureStatus] })
class AppModule {}
const app = await NestFactory.create(AppModule);
app.enableShutdownHooks();
await app.listen(3000, "127.0.0.1");
```


### publish.ts — same concrete client for every version

```typescript
import { io } from "socket.io-client";
const socket = io("http://127.0.0.1:3000", {
  path: "/socket.io", transports: ["websocket"], autoConnect: false, reconnection: false
});
function connectOnce(): Promise<void> {
  return new Promise((resolve, reject) => {
    const cleanup = () => { clearTimeout(timer); socket.off("connect", ready); socket.off("connect_error", failed); };
    const ready = () => { cleanup(); resolve(); };
    const failed = (error: Error) => { cleanup(); reject(error); };
    const timer = setTimeout(() => failed(new Error("connect timeout")), 3000);
    socket.once("connect", ready).once("connect_error", failed);
    socket.connect();
  });
}
function publish(): Promise<string> {
  return new Promise((resolve, reject) => {
    socket.timeout(2000).emit("order", { id: "order-41", sku: "book" }, (error: Error | null, receipt: string) => {
      if (error) reject(new Error("acknowledgement unknown")); else resolve(receipt);
    });
  });
}
try {
  await connectOnce();
  console.log(await publish());
  socket.disconnect();
  await connectOnce();
  console.log(await publish());
  socket.disconnect();
  console.log(await (await fetch("http://127.0.0.1:8089/charges")).text());
} finally { socket.disconnect(); }
