worker.ts:

```typescript
import 'reflect-metadata';
import { Module } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { BullModule, Processor, WorkerHost } from '@nestjs/bullmq';
import { Job } from 'bullmq';
import { writeFile } from 'node:fs/promises';
@Processor('invoices')
class InvoiceWorker extends WorkerHost {
  async process(job: Job<{ order: string }, string>) {
    if (process.env.STOP_AFTER_CLAIM === '1') process.exit(17);
    await writeFile('invoice-41.txt', `invoice:${job.data.order}`);
    return job.data.order;
  }
}
@Module({
  imports: [
    BullModule.forRoot({ connection: { host: '127.0.0.1', port: 6379 } }),
    BullModule.registerQueue({ name: 'invoices' }),
  ],
  providers: [InvoiceWorker],
})
class InvoiceModule {}
await NestFactory.createApplicationContext(InvoiceModule);
```

