const result = await fetch('http://127.0.0.1:3001/order', {
  method: 'POST', headers: { traceparent }, signal: AbortSignal.timeout(2000),
});
if (result.status !== 200 || await result.text() !== 'order-41') throw new Error('business request failed');
console.log('order-41');
