```typescript
import 'reflect-metadata';
import { Controller, Module } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { GrpcExceptionFilter, GrpcInvalidArgumentException, GrpcMethod, GrpcStreamCall, MicroserviceOptions, Transport } from '@nestjs/microservices';
import { status, type ServerDuplexStream } from '@grpc/grpc-js';
import { fileURLToPath } from 'node:url';
type NewOrder = { sku: string };
function createOrder(input: NewOrder): string {
  if (input.sku === '') throw new Error('sku_required');
  const stored = { id: 'order-41', sku: input.sku, internal_note: 'supplier-cost=19' };
  return stored.id;
}
@Controller()
class OrdersController {
  @GrpcMethod('Orders', 'Create')
  create(input: NewOrder): { id: string } {
    try { return { id: createOrder(input) }; }
    catch { throw new GrpcInvalidArgumentException('sku_required'); }
  }
  @GrpcStreamCall('Orders', 'CreateMany')
  createMany(stream: ServerDuplexStream<NewOrder, { id: string }>): void {
    stream.on('data', input => {
      if (stream.cancelled) return;
      try { stream.write({ id: createOrder(input) }); }
      catch { stream.destroy(Object.assign(new Error('sku_required'), { code: status.INVALID_ARGUMENT })); }
    });
    stream.on('end', () => stream.end());
  }
}
@Module({ controllers: [OrdersController] })
class AppModule {}
async function main() {
  const app = await NestFactory.createMicroservice<MicroserviceOptions>(AppModule, {
    transport: Transport.GRPC,
    options: { url: '127.0.0.1:50051', package: 'orders', protoPath: fileURLToPath(new URL('../orders.proto', import.meta.url)) }
  });
  app.useGlobalFilters(new GrpcExceptionFilter());
  await app.listen();
}
void main();
```

