// Authored shared business fixture; NOT RUN. No payment provider is called.
export type Order = { id: string; sku: string };
export async function recordOrderOnce(order: Order, signal?: AbortSignal): Promise<string> {
  if (!order || !/^order-[0-9]+$/.test(order.id) || order.sku !== "book") {
    throw new Error("invalid order");
  }
  const response = await fetch("http://127.0.0.1:8089/orders", {
    method: "POST", headers: { "content-type": "application/json" },
    body: JSON.stringify(order), signal
  });
  if (response.status !== 200) throw new Error("ledger rejected order");
  return await response.text();
}
```


