import amqp from "amqplib";
const connection = await amqp.connect("amqp://orders:orders-local-only@127.0.0.1:5672");
const channel = await connection.createConfirmChannel();
try {
  await channel.assertQueue("orders", { durable: false });
  const packet = { pattern: "orders", data: { id: "order-41", sku: "book" } };
  channel.sendToQueue("orders", Buffer.from(JSON.stringify(packet)), {
    contentType: "application/json", messageId: "order-41", persistent: false
  });
  await channel.waitForConfirms();
} finally { await channel.close(); await connection.close(); }
