fn run() {
    handle :: cache.open("redis://127.0.0.1:6380/0", "orders", Bool)
        ?? panic("cache connection failed")
    _ :: handle.set("order-41", false, ttl: 60s)
        ?? panic("cache write failed")
    value :: handle.get("order-41") ?? panic("cache read failed")
    print(value ?? panic("cache entry absent")) // false
}

