// Runtime kernel, or an expert's own: one marker, chip checked once at start.
#Multiversion(x86_64, x86_64_v2, x86_64_v3)
fn sum_sq(xs: [F32]) -> F32 {
    acc := Lanes<F32>.splat(0.0)                // 8 lanes in every copy (widest level)
    loop chunk in xs.lanes() {                  // last chunk masked
        acc += chunk * chunk                    // v3: one AVX multiply, one add; below: two of each
    }
    return acc.reduce(.Add)                     // fixed order: same bits in every copy
}
