// Expert: name one instruction for one chip level.
#Multiversion(x86_64, x86_64_v3)
fn reverse4(v: Lanes<F64, 4>) -> Lanes<F64, 4> {
    prep if $build.cpu.has(.AVX2) {
        return x86.mm256_permute4x64_pd(v, 0x1B)  // AVX2 instruction; name illustrative
    }
    return v.shuffle([3, 2, 1, 0])                 // fallback the author writes; tests compare bits
}
